import{_ as t,o as r,c as a,a6 as i}from"./chunks/framework.BBdhcoHf.js";const u=JSON.parse('{"title":"Sideband Direct Protocol (SBDP)","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/sbdp/index.md","filePath":"protocols/sbdp/index.md","lastUpdated":1771970963000}'),o={name:"protocols/sbdp/index.md"};function s(n,e,l,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /protocols/sbdp.md for this page in Markdown format</div><h1 id="sideband-direct-protocol-sbdp" tabindex="-1">Sideband Direct Protocol (SBDP) <a class="header-anchor" href="#sideband-direct-protocol-sbdp" aria-label="Permalink to “Sideband Direct Protocol (SBDP)”">​</a></h1><blockquote><p><strong>Authority</strong>: Navigation (Non-normative)<br><strong>Purpose</strong>: Overview and future roadmap for direct P2P sessions.<br><strong>Status: Stub</strong> — This protocol is not yet specified.</p></blockquote><p>SBDP is the planned direct (peer-to-peer) session protocol for Sideband. It will provide secure SBP transport without a relay, using mutual-authenticated session negotiation (ADR-015) over direct transports such as WebRTC DataChannel, QUIC, or TCP.</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>SBDP is intentionally not specified yet to avoid premature abstraction. The current architecture ensures SBDP can be added without changes to SBP or higher layers.</p><h2 id="relationship-to-other-protocols" tabindex="-1">Relationship to Other Protocols <a class="header-anchor" href="#relationship-to-other-protocols" aria-label="Permalink to “Relationship to Other Protocols”">​</a></h2><table tabindex="0"><thead><tr><th>Protocol</th><th>Role</th></tr></thead><tbody><tr><td>SBP</td><td>Application framing (used unchanged)</td></tr><tr><td>SBRP</td><td>Relay-based secure session</td></tr><tr><td>SBDP</td><td>Direct secure session (this protocol)</td></tr></tbody></table><h2 id="delegation" tabindex="-1">Delegation <a class="header-anchor" href="#delegation" aria-label="Permalink to “Delegation”">​</a></h2><p>This protocol delegates:</p><ul><li><strong>Wire format</strong>: Inherits SBP frame structure (see <a href="./../sbp/wire-format">sbp/wire-format.md</a>)</li><li><strong>Error codes</strong>: Reuses SBP error semantics (see <a href="./../sbp/errors">sbp/errors.md</a>)</li><li><strong>Ordering</strong>: Inherits SBP ordering guarantees (see <a href="./../sbp/behavior">sbp/behavior.md</a>)</li></ul><p>This protocol will define:</p><ul><li><strong>P2P session establishment</strong>: Direct connection setup</li><li><strong>Noise XX session negotiation</strong>: Mutual authentication and key derivation</li><li><strong>NAT traversal</strong>: ICE/STUN/TURN or similar</li></ul><h2 id="design-principles-preview" tabindex="-1">Design Principles (Preview) <a class="header-anchor" href="#design-principles-preview" aria-label="Permalink to “Design Principles (Preview)”">​</a></h2><ul><li>No relay dependency</li><li>Secure session establishment (Noise XX per ADR-015)</li><li>Reuse SBP framing unchanged</li><li>Pluggable transport (WebRTC, raw UDP, etc.)</li></ul><h2 id="document-authority" tabindex="-1">Document Authority <a class="header-anchor" href="#document-authority" aria-label="Permalink to “Document Authority”">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Primary</th><th>Supporting</th></tr></thead><tbody><tr><td>All</td><td><em>Not yet specified</em></td><td>—</td></tr></tbody></table><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to “Related Documents”">​</a></h2><ul><li><a href="./../stack">Protocol Architecture</a>: Layer stack, wrapping rules</li><li><a href="./../sbp/">SBP Specification</a>: Application framing (will be used unchanged)</li><li><a href="./../sbrp/">SBRP Specification</a>: Reference implementation for session layer</li></ul><p><em>No normative specification exists at this time.</em></p>',20)])])}const b=t(o,[["render",s]]);export{u as __pageData,b as default};
